#include <vector>
#include <functional>
#include <cmath>
#include <utility>
std::vector<std::vector<int>> queens(int n){std::vector<std::vector<int>>out;std::vector<int>path;std::function<void()>search=[&](){int row=path.size();if(row==n){out.push_back(path);return;}for(int col=0;col<n;col++){bool valid=true;for(int r=0;r<row;r++)if(path[r]==col||std::abs(path[r]-col)==row-r){valid=false;break;}if(valid){path.push_back(col);search();path.pop_back();}}};search();return out;}
std::vector<std::vector<int>> subsets(const std::vector<int>& values){std::vector<std::vector<int>>out;std::vector<int>path;std::function<void(unsigned)>search=[&](unsigned i){if(i==values.size()){out.push_back(path);return;}search(i+1);path.push_back(values[i]);search(i+1);path.pop_back();};search(0);return out;}
std::vector<std::vector<int>> permutations(const std::vector<int>& values){std::vector<std::vector<int>>out;std::vector<int>path;std::vector<bool>used(values.size());std::function<void()>search=[&](){if(path.size()==values.size()){out.push_back(path);return;}for(unsigned i=0;i<values.size();i++)if(!used[i]){used[i]=true;path.push_back(values[i]);search();path.pop_back();used[i]=false;}};search();return out;}
struct Sudoku {std::vector<std::vector<int>>board;int visits=0;bool exhausted=false;explicit Sudoku(const std::vector<std::vector<int>>& input):board(input){}bool legal(int r,int c,int v){for(int i=0;i<9;i++)if(board[r][i]==v||board[i][c]==v)return false;for(int a=r/3*3;a<r/3*3+3;a++)for(int b=c/3*3;b<c/3*3+3;b++)if(board[a][b]==v)return false;return true;}bool solve(){if(++visits>3000){exhausted=true;return false;}int row=-1,col=-1;std::vector<int>choices;for(int r=0;r<9;r++)for(int c=0;c<9;c++)if(!board[r][c]){std::vector<int>options;for(int v=1;v<=9;v++)if(legal(r,c,v))options.push_back(v);if(options.empty())return false;if(row==-1||options.size()<choices.size()){row=r;col=c;choices=options;}}if(row==-1)return true;for(int v:choices){board[row][col]=v;if(solve())return true;board[row][col]=0;if(exhausted)return false;}return false;}};
